refused_program.body:
set -u

git fetch {upstream_remote} {upstream_branch}

gitdir=$(git rev-parse --git-dir)
if [ ! -f "$gitdir/MERGE_HEAD" ]; then
  git merge --no-edit {upstream_remote}/{upstream_branch} || true
fi

conflicted=$(git diff --name-only --diff-filter=U)
if [ -z "$conflicted" ]; then
  echo "nothing conflicted to resolve"
  exit 0
fi

tmpdir=$(mktemp -d)
for f in $conflicted; do
  base=$(git rev-parse ":1:$f" 2>/dev/null || true)
  ours=$(git rev-parse ":2:$f" 2>/dev/null || true)
  theirs=$(git rev-parse ":3:$f" 2>/dev/null || true)
  if [ -z "$base" ] || [ -z "$ours" ] || [ -z "$theirs" ]; then
    echo "skipping $f: incomplete merge stages" >&2
    continue
  fi

  # what the local side added, relative to the merge base
  git diff --no-color -U1 "$base" "$ours" > "$tmpdir/local.diff"

  # keep only true insertions (a '+' run not preceded by a '-' run, i.e. not a
  # replacement) and remember the unchanged line they follow, as an anchor
  awk '
    {
      if ($0 ~ /^\+/ && $0 !~ /^\+\+\+/) { n++; add[n] = substr($0, 2); next }
      if (n > 0) {
        if (kind == "ctx") { for (i = 1; i <= n; i++) print anchor "\t" add[i] }
        else if (kind == "other" && nctx == 0) { for (i = 1; i <= n; i++) print "@@FILEHEAD@@" "\t" add[i] }
        n = 0
      }
      if ($0 ~ /^-/ && $0 !~ /^---/) { kind = "del" }
      else if ($0 ~ /^ /) { kind = "ctx"; nctx++; anchor = substr($0, 2) }
      else { kind = "other" }
    }
    END {
      if (n > 0 && kind == "ctx") { for (i = 1; i <= n; i++) print anchor "\t" add[i] }
      else if (n > 0 && kind == "other" && nctx == 0) { for (i = 1; i <= n; i++) print "@@FILEHEAD@@" "\t" add[i] }
    }
  ' "$tmpdir/local.diff" > "$tmpdir/inserts"

  # start from upstream, then put the local insertions back in place
  git show "$theirs" > "$tmpdir/upstream"

  awk -F'\t' '
    NR == FNR { extra[$1] = extra[$1] $2 "\n"; next }
    {
      if (!started) {
        started = 1
        if ("@@FILEHEAD@@" in extra) { printf "%s", extra["@@FILEHEAD@@"]; delete extra["@@FILEHEAD@@"] }
      }
      print
      if ($0 in extra) { printf "%s", extra[$0]; delete extra[$0] }
    }
  ' "$tmpdir/inserts" "$tmpdir/upstream" > "$tmpdir/resolved"

  cat "$tmpdir/resolved" > "$f"
  git add -- "$f"
done
rm -rf "$tmpdir"

git commit --no-edit
